public java.lang.String entriesAsString() {
    java.lang.StringBuilder result = new java.lang.StringBuilder();
    for (ypa.model.KEntry entry : this.entries) {
        result.append(entry).append("\n");
    }
    return result.toString();
}

public java.lang.String gridAsString() {
    final java.lang.StringBuilder result = new java.lang.StringBuilder();
    java.lang.String[][] puzzleAsString = new java.lang.String[this.matrix.size()][this.matrix.get(0).size()];
    // Add all grid cells as strings
    for (int r = 0; r < this.matrix.size(); r++) {
        for (int c = 0; c < this.matrix.get(0).size(); c++) {
            puzzleAsString[r][c] = this.matrix.get(r).get(c).toString();
        }
    }
    // Add all grid entries as strings (the Sujiko circles)
    for (ypa.model.KEntry entry : this.entries) {
        ypa.model.Location loc = entry.getLocation();
        int specSum = entry.getSpecification().getSum();
        puzzleAsString[loc.getRow() - 1][loc.getColumn() - 1] = java.lang.Integer.toString(specSum);
    }
    // Print the whole thing
    for (java.lang.String[] row : puzzleAsString) {
        for (java.lang.String cellAsString : row) {
            result.append(" ");
            result.append(cellAsString);
        }
        result.append("\n");
    }
    return result.toString();
}

