public void undo(final boolean redoable) throws java.lang.IllegalStateException {
    // # BEGIN TODO Implementation of undo
    if (!this.canUndo()) {
        throw new java.lang.IllegalStateException("There are no recent commands");
    }
    ypa.command.Command command = this.undoStack.pop();
    command.revert();
    if (redoable) {
        this.redoStack.push(command);
    }
    // # END TODO
}

