// private final EnumMap<Direction, KSpec> totals;
// Representation invariants:
// nRows == matrix.size()
// if nRows == 0
// then nColumns == 0
// else (\forall i; matrix.has(i); matrix.get(i).size() == nColumns)
// this.entries refers only to non-blocked cells in the matrix
// each entry cell has exactly four cells,
// All diagonally adjecent
public KGrid(final java.util.Scanner scanner) {
    super();
    this.matrix = new java.util.ArrayList<java.util.List<ypa.model.KCell>>();
    this.entries = ypa.model.KEntry.scanEntries(scanner);
    // Initialize the grid to be just big enough to contain all entries.
    // 1. Find out the required dimensions.
    final ypa.model.Location dim = ypa.model.KEntry.dimensions(this.entries);
    this.nRows = dim.getRow();
    this.nColumns = dim.getColumn();
    // 2. Initialize the matrix to all blocked cells.
    for (int rowIndex = 0; rowIndex != this.nRows; ++rowIndex) {
        final java.util.List<ypa.model.KCell> row = new java.util.ArrayList<ypa.model.KCell>();
        this.matrix.add(row);
        for (int columnIndex = 0; columnIndex != this.nColumns; ++columnIndex) {
            final ypa.model.KCell cell = new ypa.model.KCell(ypa.model.KCell.BLOCKED);
            cell.setGrid(this);
            cell.setLocation(new ypa.model.Location(rowIndex + 1, columnIndex + 1));
            row.add(cell);
            ypa.model.KGrid.associate(cell, this);
        }
    }
    // 3. Put cells in groups (associate cells)
    for (ypa.model.KEntry entry : this.entries) {
        ypa.model.Location entryLoc = entry.getLocation();
        int[] diagonal = new int[]{ -1, 1 };
        for (int vert : diagonal) {
            for (int hor : diagonal) {
                ypa.model.Location loc = new ypa.model.Location(entryLoc.getRow() + vert, entryLoc.getColumn() + hor);
                final ypa.model.KCell cell = this.getCell(loc.getRow() - 1, loc.getColumn() - 1);
                cell.setState(ypa.model.KCell.EMPTY);// must be done before associate

                ypa.model.KGrid.associate(cell, entry);
            }
        }
    }
    if (!scanner.hasNext("=")) {
        return;
    }
    // Read states of non-blocked non-empty cells from scanner
    scanner.skip("=");
    while (scanner.hasNext()) {
        ypa.model.Location location = new ypa.model.Location(scanner);
        scanner.next("=");
        ypa.model.KCell cell = new ypa.model.KCell(scanner);// temporary cell to get state

        this.getCell(location.getRow() - 1, location.getColumn() - 1).setState(cell.getState());
    } 
}

