private void jMenuItemSaveAsActionPerformed(java.awt.event.ActionEvent evt) {
    // GEN-FIRST:event_jMenuItemSaveAsActionPerformed
    if (this.puzzle == null) {
        this.jTextArea.append("No puzzle to save.\n");
        return;
    }
    int result = this.puzzleChooser.showSaveDialog(this);
    if (result != javax.swing.JFileChooser.APPROVE_OPTION) {
        this.jTextArea.append("Save canceled by user.\n");
        return;// canceled or error

    }
    java.io.File puzzleFile = this.puzzleChooser.getSelectedFile();
    if (puzzleFile.exists()) {
        int response = javax.swing.JOptionPane.showConfirmDialog(this, "Overwrite existing file?", "Confirm Overwrite", javax.swing.JOptionPane.OK_CANCEL_OPTION, javax.swing.JOptionPane.QUESTION_MESSAGE);
        if (response == javax.swing.JOptionPane.CANCEL_OPTION) {
            this.jTextArea.append("Overwrite canceled by user.\n");
            return;
        }
    }
    // can write puzzleFile
    java.io.PrintWriter out;
    try {
        out = new java.io.PrintWriter(puzzleFile);
        out.print(this.puzzle);
        out.close();
        this.unsavedModifications = false;
    } catch (java.io.FileNotFoundException e) {
        javax.swing.JOptionPane.showMessageDialog(this, "IO error while saving file: " + e, "File Save Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    }
}// GEN-LAST:event_jMenuItemSaveAsActionPerformed

