private void jMenuItemOpenActionPerformed(java.awt.event.ActionEvent evt) {
    // GEN-FIRST:event_jMenuItemOpenActionPerformed
    if (!this.confirmDiscard()) {
        return;
    }
    int result = this.puzzleChooser.showOpenDialog(this);
    if (result != javax.swing.JFileChooser.APPROVE_OPTION) {
        this.jTextArea.append("Open canceled by user.\n");
        return;// canceled or error

    }
    java.io.File puzzleFile = this.puzzleChooser.getSelectedFile();
    final java.util.Scanner scanner;
    try {
        scanner = new java.util.Scanner(puzzleFile);
    } catch (java.io.FileNotFoundException e) {
        this.jTextArea.append("File not found:\n");
        this.jTextArea.append(("  " + puzzleFile.getName()) + "\n");
        this.jTextArea.append(e + "\n");
        return;
    }
    try {
        this.puzzle = new ypa.model.KPuzzle(scanner, puzzleFile.getName());
        this.setTitle("Sujiko Puzzle Assistant: " + this.puzzle.getName());
        this.jTextArea.append(("Loaded puzzle from file " + this.puzzle.getName()) + "\n");
        this.jTextArea.append(this.puzzle.toString() + "\n");
        this.puzzlePanel.setPuzzle(this.puzzle);
        if (ypa.gui.MainFrame.UNDO) {
            // Clear undo-redo facility
            this.undoRedo.clear();
            // 
        }
        this.unsavedModifications = false;
        this.updateModeRadioButtons(ypa.model.KPuzzle.Mode.SOLVE);
        this.updateFrame();
    } catch (java.lang.IllegalArgumentException e) {
        this.jTextArea.append("File does not contain a puzzle description:\n");
        this.jTextArea.append(("  " + puzzleFile.getName()) + "\n");
        this.jTextArea.append(e + "\n");
    }
}// GEN-LAST:event_jMenuItemOpenActionPerformed

