static java.util.List<ypa.model.KEntry> scanEntries(final java.util.Scanner scanner) {
    java.util.List<ypa.model.KEntry> result = new java.util.ArrayList<ypa.model.KEntry>();
    java.util.regex.Pattern original = scanner.delimiter();
    scanner.skip("\\p{javaWhitespace}*");
    scanner.useDelimiter("");
    while (scanner.hasNext("[a-zA-Z]")) {
        scanner.useDelimiter(original);
        try {
            result.add(new ypa.model.KEntry(scanner));
        } catch (java.lang.Exception e) {
            throw new java.lang.IllegalArgumentException(((ypa.model.KEntry.class.getSimpleName() + ".scanEntries(Scanner).pre failed: after ") + result.size()) + " entries");
        }
        scanner.skip("\\p{javaWhitespace}*");
        scanner.useDelimiter("");
    } 
    scanner.useDelimiter(original);
    return result;
}

