    java.lang.String expResult = """
    b 2 17
    d 2 18
    b 4 15
    d 4 15
    """;
    java.lang.String expMatrix = """
     . \\ . \\ .
     \\ 17 \\ 15 \\
     . \\ . \\ .
     \\ 18 \\ 15 \\
     . \\ . \\ .
    """;
    final ypa.model.KGrid instance;
    instance = new ypa.model.KGrid(new java.util.Scanner(expResult));
    java.lang.System.out.println(instance);
    java.lang.System.out.println(instance.gridAsString());
    this.assertAll(() -> this.assertEquals(5, instance.getRowCount(), "getRowCount"), () -> this.assertEquals(5, instance.getColumnCount(), "getColumnCount"), () -> this.assertEquals(expResult, instance.entriesAsString(), "entriesAsString"), () -> this.assertEquals(expMatrix, instance.gridAsString(), "matrixAsString"), () -> this.assertEquals(16, instance.getStateCount(KCell.BLOCKED), "# blocked cells"), () -> this.assertEquals(9, instance.getStateCount(KCell.EMPTY), "# empty cells"), () -> this.assertFalse(instance.isFull(), "isFull"), () -> this.assertTrue(instance.isValid(), "isValid"));
}

