@java.lang.Override
ypa.command.CompoundCommand applyToCell(final ypa.model.KCell cell) throws java.lang.NullPointerException {
    if (!this.puzzle.isValid()) {
        return null;
    }
    ypa.command.CompoundCommand result = super.applyToCell(cell);
    ypa.command.CompoundCommand candidateForcedCommand = null;// command that worked, if any

    for (int state = this.puzzle.getMinNumber(); state <= this.puzzle.getMaxNumber(); ++state) {
        ypa.command.CompoundCommand command = new ypa.command.CompoundCommand();
        command.add(new ypa.command.SetCommand(cell, state));
        command.execute();
        ypa.command.CompoundCommand compound = this.reasoner.apply();
        if (compound != null) {
            // no contradiction
            command.add(compound);
        }
        command.revert();
        if (compound != null) {
            // no contraction; command is a candidate
            if (candidateForcedCommand == null) {
                // first command that is valid; memorize it
                candidateForcedCommand = command;
            } else {
                // multiple valid ways of filling cell; no forced command
                return result;
            }
        }
    }
    // at most one command worked
    if (candidateForcedCommand == null) {
        // all commands failed: puzzle not solvable
        return null;
    } else {
        // exactly one command worked
        result.add(candidateForcedCommand);
        return result;
    }
}

