public ypa.model.KCell mouseToCell(final java.awt.event.MouseEvent evt) {
    if (this.puzzle == null) {
        return null;
    }
    // Comment in to see cursor click location.
    // System.out.println("" + evt.getY() + ", "+ evt.getX());
    int row = (evt.getY() - this.offsetY) / this.cellSize;
    int col = (evt.getX() - this.offsetX) / this.cellSize;
    // Multiple all rows to work with coordinate system.
    row = row * 2;
    col = col * 2;
    // Cursor is in top left circle
    if ((java.lang.Math.abs(evt.getX() - (this.cellSize * 2)) < this.circleRadius) && (java.lang.Math.abs(evt.getY() - (this.cellSize * 2)) < this.circleRadius)) {
        return null;
    }
    // Cursor is in top right circle.
    if ((java.lang.Math.abs(evt.getX() - (this.cellSize * 3)) < this.circleRadius) && (java.lang.Math.abs(evt.getY() - (this.cellSize * 2)) < this.circleRadius)) {
        return null;
    }
    // Cursor is in bottom left circle.
    if ((java.lang.Math.abs(evt.getX() - (this.cellSize * 2)) < this.circleRadius) && (java.lang.Math.abs(evt.getY() - (this.cellSize * 3)) < this.circleRadius)) {
        return null;
    }
    // Cursor is in bottom right circle.
    if ((java.lang.Math.abs(evt.getX() - (this.cellSize * 3)) < this.circleRadius) && (java.lang.Math.abs(evt.getY() - (this.cellSize * 3)) < this.circleRadius)) {
        return null;
    }
    if (this.puzzle.has(row, col)) {
        return this.puzzle.getCell(row, col);
    } else {
        return null;
    }
}

