@java.lang.Override
public void revert() {
    if (this.size() != 0) {
        super.revert();
    }
    // Revert commands in reverse order
    for (int i = this.sequence.size() - 1; 0 <= i; --i) {
        final ypa.command.Command command = this.sequence.get(i);
        command.revert();
    }
}

