public static ypa.model.Location dimensions(final java.util.List<ypa.model.KEntry> entries) {
    int maxDim = -1;// largest coordinate encountered (always square)

    for (ypa.model.KEntry entry : entries) {
        final int row = entry.getLocation().getRow();
        final int column = entry.getLocation().getColumn();
        if (row > maxDim) {
            maxDim = row;
        }
        if (column > maxDim) {
            maxDim = column;
        }
    }
    return new ypa.model.Location(maxDim + 1, maxDim + 1);
}

