@java.lang.Override
ypa.command.CompoundCommand applyToCell(ypa.model.KCell cell) throws java.lang.NullPointerException {
    if (!cell.isEmpty()) {
        throw new java.lang.IllegalArgumentException(this.getClass().getSimpleName() + "applyToCell.pre failed: cell is not empty");
    }
    ypa.command.CompoundCommand result = super.applyToCell(cell);
    for (ypa.model.AbstractGroup g : cell.groups()) {
        if ((g instanceof ypa.model.KEntry) && (g.getStateCount(ypa.model.KCell.EMPTY) == 1)) {
            // g is a horizontal or vertical entry with one empty cell
            int sum = ((ypa.model.KEntry) (g)).getSpecification().getSum();
            int newState = sum - g.getTotal();
            if (!this.puzzle.isValidNumber(newState)) {
                return null;
            }
            final ypa.command.Command command = new ypa.command.SetCommand(cell, newState);
            command.execute();
            final boolean valid = this.puzzle.isValid();
            command.revert();
            if (valid) {
                result.add(command);
                return result;
            } else {
                return null;
            }
        }
    }
    return result;
}

