private void checkUndoAll(final boolean redoable) {
    final java.lang.StringBuilder trace = new java.lang.StringBuilder();
    for (final java.lang.String message : new java.lang.String[]{ "A", "B", "C" }) {
        final ypa.command.Command command = new ypa.command.UndoRedoTest.TestCommand() {
            3() {
                super();
            }

            @java.lang.Override
            public void execute() {
                super.execute();
                trace.append('+').append(message);
            }

            @java.lang.Override
            public void revert() {
                super.revert();
                trace.append('-').append(message);
            }
        };
        this.instance.did(command);
    }
    java.lang.String expResult = "+A+B+C";
    org.junit.jupiter.api.Assertions.assertEquals(expResult, trace.toString(), "Trace before undoAll");
    this.instance.undoAll(redoable);
    this.assertFalse(this.instance.canUndo(), "not canUndo(), after undoAll");
    expResult += "-C-B-A";
    org.junit.jupiter.api.Assertions.assertEquals(expResult, trace.toString(), "Trace after undoAll");
    if (redoable) {
        // check that they are redoable
        while (this.instance.canRedo()) {
            this.instance.redo();
        } 
        expResult += "+A+B+C";
        org.junit.jupiter.api.Assertions.assertEquals(expResult, trace.toString(), "Trace after redo");
    } else {
        this.assertFalse(this.instance.canRedo(), "not canRedo(), after undoAll(false)");
    }
}

