private void jMenuItemApplyReasoningActionPerformed(java.awt.event.ActionEvent evt) {
    // GEN-FIRST:event_jMenuItemApplyReasoningActionPerformed
    java.lang.String message;
    ypa.reasoning.Reasoner reasoner = null;
    ypa.reasoning.CompoundReasoner compoundReasoner = null;
    // Optionally, configure a reasoning strategy
    // Compound reasoner contains EntryWithOneEmptyCell, so that easy
    // to see cells always get filled in, additionally GeneralizedEmptyCellByContradiction
    // is used which in turn makes use of the EntryWithOneEmptyCell reasoner
    ypa.reasoning.Reasoner reasoner1 = new ypa.reasoning.EntryWithOneEmptyCell(this.puzzle);
    ypa.reasoning.Reasoner reasoner2 = new ypa.reasoning.GeneralizedEmptyCellByContradiction(this.puzzle, reasoner1);
    compoundReasoner = new ypa.reasoning.CompoundReasoner(this.puzzle);
    compoundReasoner.add(reasoner2);
    compoundReasoner.add(reasoner1);
    reasoner = compoundReasoner;
    if (reasoner == null) {
        message = "Apply Reasoning is not yet implemented.";
    } else {
        if (!this.jCheckBoxMenuItemStopAtFirstChange.isSelected()) {
            reasoner = new ypa.reasoning.FixpointReasoner(this.puzzle, compoundReasoner);
        }
        ypa.command.CompoundCommand command = reasoner.apply();
        if (command == null) {
            message = "Puzzle is not solvable.";
        } else if (command.size() > 0) {
            this.undoRedo.did(command);
            message = ("Reasoning determined " + command.getCells().size()) + " cells.";
        } else {
            message = "Reasoning did not help.";
        }
    }
    this.jTextArea.append(message + "\n");
    this.updateFrame();
}// GEN-LAST:event_jMenuItemApplyReasoningActionPerformed

