private void jPanelPuzzleKeyTyped(java.awt.event.KeyEvent evt) {
    // GEN-FIRST:event_jPanelPuzzleKeyTyped
    this.jTextArea.append(("Key typed: " + evt.getKeyChar()) + "\n");
    if (this.puzzle == null) {
        return;
    }
    final ypa.model.KCell cell = this.puzzlePanel.getSelected();
    if (cell == null) {
        return;
    }
    // cell != null
    if (this.puzzle.getMode() != ypa.model.KPuzzle.Mode.SOLVE) {
        return;
    }
    // convert key typed to new state
    final char c = evt.getKeyChar();
    final int state;
    if (('1' <= c) && (c <= '9')) {
        state = c - '0';
    } else if ((c == '0') | (c == ' ')) {
        state = ypa.model.KCell.EMPTY;
    } else {
        return;
    }
    if (!ypa.gui.MainFrame.UNDO) {
        cell.setState(state);
    } else {
        // Create undoable set command and pass it to undo-redo facility
        this.undoRedo.did(new ypa.command.SetCommand(cell, state));
        // 
    }
    this.unsavedModifications = true;
    if (this.puzzle.isSolved()) {
        this.jTextArea.append("\n> > > Puzzle is SOLVED. < < <\n");
    }
    this.updateFrame();
}// GEN-LAST:event_jPanelPuzzleKeyTyped

