@java.lang.Override
ypa.command.CompoundCommand applyToCell(final ypa.model.KCell cell) throws java.lang.NullPointerException {
    ypa.command.CompoundCommand result = super.applyToCell(cell);
    ypa.command.Command candidateForcedCommand = null;// command that worked, if any

    for (int state = this.puzzle.getMinNumber(); state <= this.puzzle.getMaxNumber(); ++state) {
        ypa.command.Command command = new ypa.command.SetCommand(cell, state);
        command.execute();
        boolean valid = this.puzzle.isValid();
        command.revert();
        if (valid) {
            // no contraction; command is a candidate
            if (candidateForcedCommand == null) {
                // first command that is valid; memorize it
                candidateForcedCommand = command;
            } else {
                // multiple valid ways of filling cell; no forced command
                return result;
            }
        }
    }
    // at most one command worked
    if (candidateForcedCommand == null) {
        // all commands failed: puzzle not solvable
        return null;
    } else {
        // exactly one command worked
        result.add(candidateForcedCommand);
        return result;
    }
}

private void checkUndo(final boolean redoable) {
    final java.lang.StringBuilder trace = new java.lang.StringBuilder();
    final ypa.command.Command command = new ypa.command.UndoRedoTest.TestCommand() {
        1() {
            super();
        }

        @java.lang.Override
        public void revert() {
            super.revert();
            trace.append("R");
        }
    };
    this.instance.did(command);
    this.instance.undo(redoable);
    this.assertAll(() -> this.assertFalse(command.isExecuted(), "not isExecuted"), () -> this.assertFalse(instance.canUndo(), "not canUndo"), () -> this.assertEquals(redoable, instance.canRedo(), ("canRedo() after undo(" + redoable) + ")"), () -> {
        if (redoable) {
            this.assertEquals(command, instance.lastUndone(), "lastUndone");
        }
        // else: pass
    }, () -> this.assertEquals("R", trace.toString(), "Trace"));
}

