private void jMenuItemSolveActionPerformed(java.awt.event.ActionEvent evt) {
    // GEN-FIRST:event_jMenuItemSolveActionPerformed
    if (this.puzzle == null) {
        return;
    }
    // puzzle != null
    java.lang.String message;
    ypa.reasoning.Reasoner reasoner = null;
    ypa.solvers.AbstractSolver solver = null;
    // Configure and invoke solver
    reasoner = new ypa.reasoning.EntryWithOneEmptyCell(this.puzzle);
    // reasoner = new BasicEmptyCellByContradiction(puzzle);
    reasoner = new ypa.reasoning.FixpointReasoner(this.puzzle, reasoner);
    solver = new ypa.solvers.BacktrackSolver(this.puzzle, reasoner);
    // 
    if (solver == null) {
        message = "Solve is not yet implemented.";
    } else if (solver.solve()) {
        message = "Puzzle solved";
        // handle result of solver
        final java.util.Collection<ypa.command.Command> commands = solver.getCommands();
        message = ((message + ": ") + commands.size()) + " steps";
        for (final ypa.command.Command command : commands) {
            if ((command instanceof ypa.command.CompoundCommand) && (((ypa.command.CompoundCommand) (command)).size() == 0)) {
                continue;
            }
            this.undoRedo.did(command);
        }
    } else {
        message = "Puzzle not solvable";
    }
    this.jTextArea.append(message + "\n");
    this.updateFrame();
}// GEN-LAST:event_jMenuItemSolveActionPerformed

