public ypa.command.CompoundCommand apply() {
    final ypa.command.CompoundCommand result = super.apply();
    // Apply reasoner to all empty cells, execute and return command
    for (ypa.model.KCell cell : this.puzzle.getCells()) {
        if (cell.isEmpty()) {
            ypa.command.CompoundCommand command = this.applyToCell(cell);
            if (command == null) {
                return command;
            } else if (command.size() > 0) {
                command.execute();
                return command;
            }
        }
    }
    // 
    return result;
}

public static void associate(final ypa.model.KCell cell, final ypa.model.AbstractGroup group) throws java.lang.IllegalArgumentException {
    if (cell == null) {
        throw new java.lang.IllegalArgumentException(ypa.model.KGrid.class.getSimpleName() + ".associate.pre failed: cell == null");
    }
    if (group == null) {
        throw new java.lang.IllegalArgumentException(ypa.model.KGrid.class.getSimpleName() + ".associate.pre failed: group == null");
    }
    if (cell.isContainedIn(group)) {
        throw new java.lang.IllegalArgumentException(ypa.model.KGrid.class.getSimpleName() + ".associate.pre failed: cell is already associated with group");
    }
    if (group.contains(cell)) {
        throw new java.lang.IllegalArgumentException(ypa.model.KGrid.class.getSimpleName() + ".associate.pre failed: group already contains cell");
    }
    group.add(cell);
    cell.add(group);
}

