@java.lang.Override
public void paintComponent(java.awt.Graphics g) {
    super.paintComponent(g);
    g.setColor(java.awt.Color.DARK_GRAY);
    g.fillRect(0, 0, this.getWidth(), this.getHeight());
    g.setFont(new java.awt.Font("Lucida Sans Typewriter", java.awt.Font.BOLD, 24));
    if (this.puzzle == null) {
        g.setColor(java.awt.Color.YELLOW);
        g.drawString("No puzzle loaded", this.cellSize, this.cellSize);
        return;
    }
    int puzzleSquareColumns = (this.puzzle.getColumnCount() / 2) + 1;
    int puzzleSquareRows = (this.puzzle.getRowCount() / 2) + 1;
    // puzzle != null
    final int WIDTH = this.cellSize * puzzleSquareColumns;
    final int HEIGHT = this.cellSize * puzzleSquareRows;
    // WIDTH, HEIGHT includes top, left border for showing coordinates
    java.awt.FontMetrics fm = g.getFontMetrics();
    final int delta_x = ((this.cellSize - fm.charWidth('0')) / 2) + 1;
    final int delta_y = ((this.cellSize - fm.getAscent()) + fm.getDescent()) / 2;
    g.setColor(java.awt.Color.WHITE);
    g.fillRect(this.cellSize, this.cellSize, WIDTH, HEIGHT);
    g.setColor(java.awt.Color.BLACK);
    // draw all horizontal separator lines
    for (int r = 0; r <= this.puzzle.getRowCount(); ++r) {
        final int y = (r * this.cellSize) + this.offsetY;
        g.drawLine(this.offsetX, y, WIDTH + this.offsetX, y);
    }
    // draw all vertical separator lines
    for (int c = 0; c <= puzzleSquareRows; ++c) {
        final int x = (c * this.cellSize) + this.offsetX;
        g.drawLine(x, this.offsetY, x, HEIGHT + this.offsetY);
    }
    // draw cell background and contents
    for (int r = 0; r != puzzleSquareRows; ++r) {
        final int y = ((r + 1) * this.cellSize) + this.offsetY;
        for (int c = 0; c != puzzleSquareColumns; ++c) {
            final int x = (c * this.cellSize) + this.offsetX;
            // x, y = coordinate of bottom-left corner
            final ypa.model.KCell cell = this.puzzle.getCell(r * 2, c * 2);
            this.paintCell(g, cell, x, y, delta_x, delta_y);
        }
    }
    // draw entries sums
    g.setFont(new java.awt.Font("Lucida Sans Typewriter", java.awt.Font.PLAIN, 16));
    for (ypa.model.KEntry entry : this.puzzle.getEntries()) {
        final int row = entry.getLocation().getRow();// row index of cell to show sum of entry

        final int column = entry.getLocation().getColumn();// column index of cell to show sum of entry

        final int x = ((column / 2) * this.cellSize) + this.offsetX;// x-coordinate of center of circle

        final int y = ((row / 2) * this.cellSize) + this.offsetY;// y-coordinate of center of circle

        // draw white circle area
        g.setColor(java.awt.Color.WHITE);
        g.fillOval(x - this.circleRadius, y - this.circleRadius, 2 * this.circleRadius, 2 * this.circleRadius);
        // Draw black border
        g.setColor(java.awt.Color.BLACK);
        g.drawOval(x - this.circleRadius, y - this.circleRadius, 2 * this.circleRadius, 2 * this.circleRadius);
        // draw sum, in smaller font
        final int sum = entry.getSpecification().getSum();
        this.drawCenteredString(g, java.lang.String.format("%2d", sum), x, y);
        // paintCell(g, cell, x, y, delta_x, delta_y);
    }
}

