// 
@java.lang.Override
public boolean solve() {
    // Backtracking solver, using the reasoner if not null
    if (this.reasoner != null) {
        // first, fill in cells by reasoning
        final ypa.command.Command compound = this.reasoner.apply();
        if (compound == null) {
            // not solvable
            return false;
        }
        this.commands.push(compound);
    }
    final ypa.model.KCell cell = this.getEmptyCell();
    if (cell == null) {
        // no more empty cells
        return this.puzzle.isValid();
    } else {
        // cell is empty; set it in all possible ways
        for (int state = this.puzzle.getMinNumber(); state <= this.puzzle.getMaxNumber(); ++state) {
            final ypa.command.Command command = new ypa.command.SetCommand(cell, state);
            command.execute();
            if (this.puzzle.isValid()) {
                this.commands.push(command);
                // number of open cells is one less
                if (this.solve()) {
                    return true;
                }
                // no solution found
                this.commands.pop();
            }
            // restore cell state
            command.revert();
        }
    }
    if (this.reasoner != null) {
        // to revert the reasoned cells
        this.commands.pop().revert();
    }
    // 
    return false;
}

