private void paintCell(final java.awt.Graphics g, final ypa.model.KCell cell, final int x, final int y, final int delta_x, final int delta_y) {
    // set background if cell is marked
    if ((this.highlight && (this.markedCells != null)) && this.markedCells.contains(cell)) {
        g.setColor(java.awt.Color.CYAN);
        g.fillRect(x + 1, (y - this.cellSize) + 1, this.cellSize - 1, this.cellSize - 1);
    }
    if ((this.selected != null) && (cell == this.selected)) {
        g.setColor(java.awt.Color.YELLOW);
        g.fillRect(x + 1, (y - this.cellSize) + 1, this.cellSize - 1, this.cellSize - 1);
    }
    // draw cell content, if not empty
    if (cell.isBlocked()) {
        g.setColor(java.awt.Color.BLACK);
        g.fillRect(x + 1, (y - this.cellSize) + 1, this.cellSize - 1, this.cellSize - 1);
        // draw diagonal
        g.setColor(java.awt.Color.WHITE);
        g.drawLine(x, y - this.cellSize, x + this.cellSize, y);
    } else if (!cell.isEmpty()) {
        // cell occupied by a symbol
        // set color for symbol
        java.awt.Color color = java.awt.Color.BLACK;
        if (this.highlight) {
            if (!cell.isOK()) {
                color = java.awt.Color.RED;
            } else if (this.puzzle.isSolved()) {
                color = java.awt.Color.GREEN;
            }
        }
        g.setColor(color);
        g.drawString(cell.toString(), x + delta_x, y - delta_y);
    }
}

