public static int fromString(final java.lang.String s) {
    switch (s) {
        case ypa.model.KCell.BLOCKED_STR ->
            {
                return ypa.model.KCell.BLOCKED;
            }
        case ypa.model.KCell.EMPTY_STR ->
            {
                return ypa.model.KCell.EMPTY;
            }
        default ->
            {
                try {
                    int result = java.lang.Integer.parseInt(s);
                    if (result <= ypa.model.KCell.EMPTY) {
                        throw new java.lang.IllegalArgumentException(((ypa.model.KCell.class.getSimpleName() + ".fromString(") + s) + ").pre failed");
                    }
                    return result;
                } catch (java.lang.Exception e) {
                    throw new java.lang.IllegalArgumentException(((ypa.model.KCell.class.getSimpleName() + ".fromString(") + s) + ").pre failed");
                }
            }
    }
}

